const WORDS = {
  en: { nowhere: 'Nowhere in particular', alone: 'alone', with: 'with', map: 'Map', mapTitle: 'Show the map in the sidebar' },
  zh: { nowhere: '不在任何特定地点', alone: '独自一人', with: '与', map: '地图', mapTitle: '在侧栏显示地图' },
}
const words = () => WORDS[document.documentElement.lang] ?? WORDS.en
const text = (id, value) => { document.getElementById(id).textContent = value }
let latest

function render() {
  const view = latest
  if (view === undefined) return
  const w = words()
  text('place', view.place ? view.place.name : w.nowhere)
  text('time', view.time ? [view.time.text, ...view.time.holidays].join(' · ') : '')
  const here = view.place ? view.place.here.map(person => person.name) : []
  const tracked = view.variables.filter(entry => entry.subject !== 'the world').map(entry => `${entry.subject}: ${entry.name} ${entry.value}`)
  text('more', [here.length > 0 ? `${w.with} ${here.join(', ')}` : w.alone, ...tracked].join(' · '))
  const button = document.getElementById('map')
  button.textContent = w.map
  button.title = w.mapTitle
  rp.resize(document.documentElement.scrollHeight)
}

rp.watch((view) => { latest = view; render() })
rp.on('theme', render)
document.getElementById('map').addEventListener('click', () => { rp.open('sidebar').catch(error => console.warn(error)) })

add.ui/scene/map.js:
const WORDS = {
  en: { label: 'The places you know and the ways between them', empty: 'No places known yet.' },
  zh: { label: '你所知道的地点以及它们之间的路', empty: '还没有已知的地点。' },
}
const words = () => WORDS[document.documentElement.lang] ?? WORDS.en
const SVG = 'http://www.w3.org/2000/svg'
const CENTRE = 200
const RADIUS = 140

function element(name, attributes = {}, text) {
  const node = document.createElementNS(SVG, name)
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, String(value))
  if (text !== undefined) node.textContent = text
  return node
}

/** Where each known place is drawn: the one the player is in at the centre, the others around it. */
function layout(places) {
  const others = places.filter(place => !place.here)
  const spots = new Map(places.filter(place => place.here).map(place => [place.key, { x: CENTRE, y: CENTRE }]))
  others.forEach((place, index) => {
    const angle = (index / Math.max(1, others.length)) * Math.PI * 2 - Math.PI / 2
    spots.set(place.key, { x: CENTRE + RADIUS * Math.cos(angle), y: CENTRE + RADIUS * Math.sin(angle) })
  })
  return spots
}

let latest

function render() {
  const view = latest
  if (view === undefined) return
  const svg = document.getElementById('map')
  svg.setAttribute('aria-label', words().label)
  const empty = document.getElementById('empty')
  empty.textContent = words().empty
  empty.hidden = view.map.places.length > 0
  const spots = layout(view.map.places)
  svg.replaceChildren(
    ...view.map.routes.flatMap((route) => {
      const from = spots.get(route.from)
      const to = spots.get(route.to)
      return from && to ? [element('line', { class: 'edge', x1: from.x, y1: from.y, x2: to.x, y2: to.y })] : []
    }),
    ...view.map.places.map((place) => {
      const spot = spots.get(place.key)
      const group = element('g', { class: place.here ? 'node here' : 'node', transform: `translate(${spot.x} ${spot.y})` })
      group.append(element('circle', { r: place.here ? 11 : 8 }), element('text', { y: place.here ? 28 : 24 }, place.name))
      return group
    }),
  )
}

rp.watch((view) => { latest = view; render() })
rp.on('theme', render)

