:root { color-scheme: light dark; }
html, body { margin: 0; background: transparent; color: var(--dsw-alias-label-primary, CanvasText); font: 13px/20px system-ui, sans-serif; }
.muted { color: var(--dsw-alias-label-tertiary, GrayText); }
button { font: inherit; text-align: left; border: 1px solid var(--dsw-alias-border-l3, #8886); border-radius: var(--dsw-radius-sm, 8px); background: transparent; color: inherit; padding: 4px 10px; margin: 0 6px 6px 0; cursor: pointer; }
button:hover { border-color: var(--dsw-alias-brand-primary, currentColor); }
.strip { display: flex; flex-wrap: wrap; gap: 4px 14px; align-items: baseline; padding: 8px 12px; border: 1px solid var(--dsw-alias-border-l3, #8886); border-radius: var(--dsw-radius-sm, 8px); background: var(--dsw-alias-bg-layer-1, transparent); }
.strip .place { font-weight: 600; color: var(--dsw-alias-brand-primary, inherit); }
.strip .time, .strip .more { color: var(--dsw-alias-label-secondary, inherit); }
.strip button { margin: 0 0 0 auto; padding: 0 8px; }
svg { display: block; width: 100%; height: 100%; }
.edge { stroke: var(--dsw-alias-border-l2, #8888); stroke-width: 1.5; }
.node circle { fill: var(--dsw-alias-bg-layer-2, #8882); stroke: var(--dsw-alias-border-l2, #888); stroke-width: 1.5; }
.node.here circle { fill: var(--dsw-alias-brand-primary, #a52); stroke: none; }
.node text { fill: var(--dsw-alias-label-secondary, currentColor); font-size: 11px; text-anchor: middle; }
.node.here text { fill: var(--dsw-alias-label-primary, currentColor); font-weight: 600; }
.map-empty { padding: 24px; }
